  "implementation": "def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    applications = []
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            old = p['old']
            new = p['new']
            if not old:
                continue
            idx = text.find(old)
            if idx != -1:
                text = text[:idx] + new + text[idx+len(old):]
                applications.append(p['name'])
                changed = True
        if not changed:
            return {'text': text, 'applications': applications, 'fixed_point': True}
    return {'text': text, 'applications': applications, 'fixed_point': False}
